from format_lecon import Lesson,paras,table,steps
from diagnostics import comparison
from medicaments import adrenaline,icatibant
l=Lesson('Gonflement du visage, des lèvres ou du cou')
l.add('Un {gonflement cervicofacial est un signe, pas un diagnostic}. Il peut correspondre à un œdème, une infection, une obstruction ou une masse. La vitesse d’apparition et la fonction respiratoire déterminent la première décision.',paras('L’angio-œdème atteint les tissus profonds cutanés ou muqueux, alors que l’urticaire superficielle produit des plaques dermiques. Toute lèvre gonflée n’est cependant pas une réaction allergique.', 'Une tuméfaction localisée peut provenir d’une dent, d’une glande salivaire, d’un ganglion ou de la thyroïde. Un gonflement diffus du visage et du cou peut refléter un défaut de drainage veineux. Il faut nommer la structure et le mécanisme avant de choisir le traitement.'),(1,3,4,5,7))
l.add('Le {contexte modifie les probabilités sans supprimer les urgences}. Médicaments, exposition allergénique, foyer dentaire et cancer orientent. Une forme ancienne ou récidivante peut tout de même menacer les voies aériennes.',paras('Aucune série suisse homogène ne classe les dix diagnostics retenus pour l’ensemble de ce symptôme. Les données d’une consultation d’allergologie, d’un service dentaire ou d’oncologie ne doivent pas être mélangées en un classement artificiel.', 'Une histoire familiale négative n’exclut pas l’angio-œdème héréditaire, notamment en présence d’une mutation nouvelle. Une longue tolérance d’un inhibiteur de l’enzyme de conversion ne suffit pas à écarter son rôle devant un angio-œdème.', 'Douleur pendant les repas, infection récente, immunodépression, procédure dentaire, cathéter veineux et tabagisme sont des éléments contextuels utiles. Le handicap de déglutition, de respiration et d’alimentation compte davantage que le seul volume visible.'),(1,3,4,7,13))
l.add('Les {mécanismes relient anatomie, examens et traitement}. Les voies aériennes traversent une région riche en glandes, ganglions et espaces profonds. Le même aspect externe peut donc cacher des risques très différents.',table(['Mécanisme','Conséquence et examen','Action dirigée'],[['Libération mastocytaire.','Œdème, urticaire et parfois atteinte respiratoire ou circulatoire ; diagnostic clinique urgent.','Adrénaline intramusculaire si anaphylaxie, puis traitement complémentaire adapté.'],['Excès de bradykinine.','Œdème souvent sans urticaire ; analyser médicaments et C1-inhibiteur.','Protection des voies aériennes et traitement spécifique selon la cause.'],['Infection dentaire ou cervicale.','Pus, induration, trismus ou extension dans les espaces profonds.','Contrôle du foyer, drainage si indiqué et antibiothérapie adaptée.'],['Obstruction salivaire.','Gonflement rythmé par les repas ; échographie et examen du canal.','Lever l’obstacle et traiter une surinfection éventuelle.'],['Obstacle au retour veineux.','Congestion cervicofaciale et veines collatérales ; imagerie veineuse.','Traiter thrombose ou compression selon le bilan.'],['Prolifération tissulaire.','Masse persistante, ganglion ou thyroïde ; imagerie et prélèvement ciblés.','Traitement étiologique après caractérisation.']])+paras('Les espaces cervicaux peuvent communiquer avec le médiastin. Une infection cervicale profonde n’est donc pas une simple lésion de peau. Une diminution de perméabilité du larynx peut rapidement devenir critique même si le gonflement externe paraît modeste.'),(1,3,4,5,7,8,9,10))
l.add('Le {tri recherche d’abord obstruction respiratoire, anaphylaxie et infection grave}. Dysphonie, stridor, dyspnée ou impossibilité d’avaler sont des alarmes. Une masse chronique ne dispense pas de rechercher une complication aiguë.',table(['Priorité','Signes','Conduite'],[['🚩 E1','Langue ou plancher buccal gonflés, voix modifiée, stridor, stase salivaire.','Appel urgent, équipe experte des voies aériennes et surveillance ; ne pas attendre l’imagerie si la perméabilité des voies aériennes est menacée.'],['🚩 E1','Installation rapide avec atteinte respiratoire ou circulatoire compatible avec anaphylaxie.','Adrénaline intramusculaire précoce, appel au 144 et prise en charge de réanimation.'],['🚩 E1','Infection cervicale avec trismus, torticolis, dyspnée, sepsis ou extension thoracique.','Hospitalisation, protection des voies aériennes et avis chirurgical urgent.'],['🚩 E1','Congestion cervicofaciale avec détresse respiratoire ou signes neurologiques.','Évaluer en urgence une obstruction cave et ses complications.'],['E2','Masse persistante, progressive, dure ou kystique chez l’adulte.','Bilan spécialisé accéléré ; ne pas conclure bénigne sur le seul aspect kystique.']])+paras('Une anaphylaxie peut survenir sans urticaire visible. Les signes respiratoires ou circulatoires ne doivent pas attendre le résultat d’un dosage biologique. L’atteinte cutanée isolée n’est pas à elle seule synonyme d’anaphylaxie.'),(1,2,3,6,8,9,13))
l.add('L’{anamnèse précise début, rythme et facteurs déclenchants}. Demander médicaments habituels et récemment ajoutés. Rechercher douleur dentaire, repas, infection, exposition et récidives.',paras('Noter minutes, heures, jours ou semaines d’évolution. Une fluctuation liée aux repas évoque une obstruction salivaire ; une progression persistante demande de caractériser une masse. La douleur ou son absence ne suffisent pas à exclure une cause grave.', 'Rechercher urticaire, prurit, malaise, gêne respiratoire, douleur abdominale et diarrhée. Demander crises antérieures, antécédents familiaux d’œdème ou de mort inexpliquée, soins dentaires et procédures invasives.', 'Revoir les inhibiteurs de l’enzyme de conversion et autres médicaments pouvant favoriser un angio-œdème. Un patient peut ne pas connaître la classe de son traitement : vérifier l’ordonnance réelle.', 'Pour une masse cervicale, rechercher dysphonie, dysphagie, otalgie, lésion buccale, symptômes généraux et facteurs de risque. Pour une congestion diffuse, demander cathéter, pacemaker, cancer et symptômes thoraciques.'),(1,3,4,5,7,13))
l.add('L’{examen commence par la respiration et la circulation}. Observer voix, salive, langue et état général avant une palpation détaillée. Décrire ensuite siège, latéralité, douleur et consistance.',paras('Mesurer fréquence respiratoire, saturation, pouls, pression artérielle, température et conscience selon la situation. Une saturation initialement conservée ne suffit pas à rassurer devant une obstruction haute progressive.', 'Examiner peau, lèvres, langue et plancher buccal sans provoquer une détresse. Rechercher foyer dentaire, ouverture de bouche limitée, écoulement salivaire et asymétrie pharyngée. Une exploration profonde chez un patient instable relève d’une équipe équipée.', 'Palper les aires ganglionnaires et la thyroïde, préciser mobilité et caractère inflammatoire. Examiner les territoires drainés, les glandes salivaires et les autres régions selon les signes. Une masse kystique de l’adulte n’est pas déclarée congénitale sans bilan.', 'Rechercher circulation veineuse collatérale, gonflement des membres supérieurs et signes thoraciques. Documenter l’évolution pour le suivi sans retarder la prise en charge urgente.'),(1,3,4,5,6,7,8,13))
l.add('L’{approche syndromique sépare œdème, infection et masse}. L’absence d’urticaire oriente mais ne prouve pas seule un mécanisme. La localisation anatomique aide à sélectionner les examens.',paras('7.1. Un œdème rapide avec signes mastocytaires fait rechercher une anaphylaxie. Un œdème isolé sans prurit impose notamment la revue des médicaments et l’hypothèse bradykinique.', '7.2. Une tuméfaction douloureuse fébrile oriente vers un foyer dentaire, salivaire, ganglionnaire ou profond. Trismus, stase salivaire et dyspnée changent la priorité.', '7.3. Une masse persistante nécessite de distinguer glande thyroïde, ganglion, lésion salivaire et autre tumeur. Une congestion diffuse avec veines collatérales évoque un obstacle veineux.', 'Les dix hypothèses ne couvrent pas toutes les causes : traumatisme, hématome, infection cutanée, œdème systémique et autres maladies inflammatoires doivent rester envisagés selon le tableau.')+comparison(),(1,3,4,5,6,7,8,9,10,13))
l.add('Le {diagnostic positif doit nommer le mécanisme ou la lésion}. Le gonflement seul ne suffit pas à prescrire un traitement causal. La gravité reste évaluée pendant le bilan.',paras('L’anaphylaxie est un diagnostic clinique aigu fondé sur le contexte et les atteintes d’organes. L’absence de manifestations cutanées n’élimine pas une réaction grave. Une atteinte isolée des lèvres ne prouve pas une défaillance systémique.', 'L’angio-œdème bradykinique est évoqué par l’absence d’urticaire, l’histoire médicamenteuse ou des crises récidivantes, mais demande une analyse spécialisée. Une mauvaise réponse aux antihistaminiques peut renforcer le doute sans remplacer le bilan.', 'Pour une infection, identifier le foyer et l’extension. Pour une masse, combiner examen, imagerie et prélèvement adapté. L’imagerie seule ne distingue pas toujours une adénopathie kystique bénigne d’une lésion maligne.'),(1,3,6,8,9,10))
l.add('Les {examens complémentaires répondent à une hypothèse précise}. Aucun test unique ne couvre toutes les tuméfactions. La sécurisation respiratoire précède les examens qui pourraient la retarder.',paras('9.a. L’évaluation clinique est centrale pour l’urgence. Les examens identifient ensuite la cause et l’extension.', '9.b. Selon le tableau, obtenir bilan inflammatoire et infectieux, exploration du foyer dentaire, échographie salivaire, ganglionnaire ou thyroïdienne. La TSH évalue la fonction thyroïdienne ; elle ne définit pas seule la nature d’une masse.', '9.c. Un examen incomplet ou une imagerie non disponible impose une stratégie de remplacement ou un transfert adapté. Ne pas conclure à une absence de danger sur l’absence d’examen.', '9.d. Une infection profonde demande souvent une imagerie injectée et un avis chirurgical. Une suspicion d’angio-œdème héréditaire ou acquis conduit aux dosages du complément et du C1-inhibiteur. Une congestion veineuse oriente vers Doppler ou imagerie thoracique avec contraste selon la question.')+table(['Résultat','Décision'],[['Une collection ou extension profonde est démontrée.','Coordonner drainage, antibiothérapie et surveillance.'],['Une anomalie du C1-inhibiteur est retrouvée.','Confirmer et classer avec le spécialiste ; organiser traitement et plan d’urgence.'],['Une masse kystique cervicale est présente chez l’adulte.','Poursuivre le bilan oncologique approprié, sans conclure sur l’image seule.'],['Une obstruction veineuse est identifiée.','Traiter selon thrombose, compression et gravité.']]),(1,3,4,5,6,9,10,13))
l.add('L’{algorithme commence par le danger immédiat}. Après sécurisation, classer le tableau clinique et localiser l’origine. Réévaluer rapidement toute discordance avec l’évolution.',steps('Rechercher atteinte des voies aériennes, anaphylaxie, sepsis et signes de compression grave.', 'Traiter l’urgence et appeler l’équipe appropriée avant examens non indispensables.', 'Distinguer œdème rapide, infection localisée ou profonde, masse et congestion veineuse.', 'Choisir examens et traitement dirigés par ce mécanisme, avec revue des médicaments.', 'Organiser une réévaluation et un plan de retour, particulièrement si la cause reste incertaine.'),(1,3,6,8,9,10,13))
ad=adrenaline(l);ic=icatibant(l)
l.add('La {prise en charge traite la cause et protège les fonctions vitales}. Un antihistaminique ne remplace pas le traitement d’une anaphylaxie. Un antibiotique ne remplace pas toujours le drainage d’un foyer.',paras('11.A. Préserver respiration, circulation et déglutition, puis réduire douleur et gonflement. Le choix du lieu de soins dépend de la gravité et de la possibilité d’une progression.', '11.B. Pour une atteinte histaminergique cutanée isolée, les antihistaminiques de deuxième génération peuvent être utiles selon le diagnostic. Les augmentations de dose mentionnées dans les stratégies d’urticaire ne sont pas automatiquement des doses autorisées pour toute spécialité.', '11.B. L’angio-œdème associé à un inhibiteur de l’enzyme de conversion impose son arrêt et une substitution médicale adaptée. Un traitement spécifique de l’angio-œdème héréditaire ne doit pas être présumé autorisé pour cette autre indication.', '11.B. Les crises héréditaires demandent un traitement précoce selon le plan spécialisé. '+ic, '11.C. En cas d’anaphylaxie, administrer précocement l’adrénaline intramusculaire et obtenir une aide urgente. '+ad, '11.C. Les infections profondes nécessitent prise en charge hospitalière, contrôle du foyer et antibiothérapie. Pour un abcès dentaire, le drainage et le traitement causal sont fondamentaux ; les antibiotiques répondent à une diffusion, une atteinte systémique ou une impossibilité de drainage immédiat selon le guide écossais.', '11.D. Une sortie nécessite disparition de la menace immédiate, compréhension des consignes et suivi accessible. L’observation après anaphylaxie est individualisée selon gravité et risque de récidive. Toute atteinte laryngée héréditaire nécessite une surveillance médicale même après traitement à domicile.', 'Une masse persistante, un goitre compressif ou un syndrome cave demande son parcours spécialisé. Grossesse, âge, fonction rénale ou hépatique et interactions modifient le choix des médicaments ; ils ne justifient pas de retarder une mesure vitale.'),(1,3,5,6,8,9,10,11,12,13))
l.add('La {prévention associe traitement du foyer et plan d’urgence}. Informer sur les médicaments responsables et les signes de gravité. Le suivi évite de perdre de vue une masse persistante.',paras('La prévention primaire comprend soins dentaires, réduction des facteurs de risque et revue des prescriptions selon le diagnostic. Un antécédent d’angio-œdème médicamenteux doit être clairement documenté.', 'La prévention secondaire identifie précocement une récidive, une extension infectieuse ou une masse progressive. Après réaction allergique grave, le bilan spécialisé prépare éviction, matériel et formation au traitement d’urgence.', 'La prévention tertiaire organise le plan des crises héréditaires et les mesures avant procédures à risque avec le spécialiste. Les proches doivent connaître les signes respiratoires et la nécessité d’appeler les secours même si un traitement a déjà été donné.'),(1,3,6,8,9,10,12))
l.add('Les {points clés privilégient le mécanisme et les fonctions vitales}. Une lèvre gonflée n’est pas toujours allergique. Une masse kystique adulte n’est pas toujours bénigne.',paras('Dysphonie, stridor, dyspnée et stase salivaire sont prioritaires. L’adrénaline intramusculaire est centrale dans l’anaphylaxie, mais ne corrige pas le mécanisme bradykinique. Une infection profonde peut menacer le médiastin et les voies aériennes. L’évolution et la réponse au traitement doivent rester cohérentes avec le diagnostic retenu.'),(1,3,6,8,9,10))
l.quiz([('Tout gonflement des lèvres est-il allergique ?','Non.'),('Une anaphylaxie peut-elle survenir sans urticaire ?','Oui.'),('Un antihistaminique traite-t-il une défaillance circulatoire anaphylactique ?','Non ; l’adrénaline intramusculaire et la prise en charge urgente sont prioritaires.'),('Une longue tolérance d’un inhibiteur de l’enzyme de conversion exclut-elle son rôle ?','Non.'),('Une histoire familiale négative exclut-elle l’angio-œdème héréditaire ?','Non.'),('Une injection à domicile permet-elle de rester chez soi avec œdème laryngé ?','Non ; une observation médicale est nécessaire.'),('Un gonflement rythmé par les repas évoque-t-il une obstruction salivaire ?','Oui.'),('Trismus et plancher buccal induré doivent-ils être banalisés ?','Non ; rechercher une infection profonde et une menace respiratoire.'),('Les antibiotiques remplacent-ils toujours le drainage d’un abcès dentaire ?','Non.'),('Une masse cervicale kystique de l’adulte est-elle forcément bénigne ?','Non.'),('Une TSH normale exclut-elle un goitre compressif ?','Non.'),('Un cathéter peut-il contribuer à un syndrome cave supérieur ?','Oui, notamment par thrombose.'),('Les doses de l’arrêt cardiaque sont-elles celles d’une anaphylaxie ordinaire ?','Non ; vérifier indication, concentration et voie.'),('Les dix diagnostics sont-ils classés par prévalence suisse démontrée ?','Non ; leur ordre est pédagogique.')],(1,3,4,5,6,8,9,10,11,12,13))
l.write()
